177	  async criar(body: {
178	    restaurant_id: number;
179	    customer_id?: number;
180	    payment_method: string;
181	    troco_para?: number;
182	    user_id: string;
183	    itens: { product_id?: number; combo_id?: number; quantity: number }[];
184	  }) {
185	    if (!body.itens?.length) throw new BadRequestException('Pedido precisa de pelo menos 1 item');
186	
187	    const itensDiretos = body.itens.filter((i) => i.product_id != null);
188	    const itensCombo = body.itens.filter((i) => i.combo_id != null);
189	
190	    // Busca preços dos produtos vendidos diretamente (fora de combo)
191	    const prodIds = itensDiretos.map((i) => i.product_id as number);
192	    const { data: produtos, error: errProd } = await this.supabase.client
193	      .from('products')
194	      .select('id, price, is_active')
195	      .in('id', prodIds.length ? prodIds : [0]);
196	
197	    if (errProd) throw errProd;
198	
199	    const prodMap = Object.fromEntries((produtos ?? []).map((p) => [p.id, p]));
200	
201	    for (const item of itensDiretos) {
202	      const prod = prodMap[item.product_id as number];
203	      if (!prod) throw new BadRequestException(`Produto ${item.product_id} não encontrado`);
204	      if (!prod.is_active) throw new BadRequestException(`Produto ${item.product_id} inativo`);
205	    }
206	
207	    // Combo não é vendável direto — vira as linhas dos produtos reais que o compõem,
208	    // com preço escalado pra bater o valor promocional do combo (ver CombosService).
209	    const linhasCombo: ItemExpandido[] = (
210	      await Promise.all(itensCombo.map((i) => this.combos.expandir(i.combo_id as number, i.quantity, body.restaurant_id)))
211	    ).flat();
212	
213	    const linhasDiretas: ItemExpandido[] = itensDiretos.map((item) => ({
214	      product_id: item.product_id as number,
215	      quantity: item.quantity,
216	      unit_price: prodMap[item.product_id as number].price,
217	    }));
218	
219	    const linhasFinais = [...linhasDiretas, ...linhasCombo];
220	
221	    const subtotal = linhasFinais.reduce((acc, l) => acc + l.unit_price * l.quantity, 0);
222	
223	    // Busca frete do restaurante e soma ao total
224	    const { data: rest } = await this.supabase.client
225	      .from('restaurants')
226	      .select('frete_motoboy, motoboy_comissao_tipo')
227	      .eq('id', body.restaurant_id)
228	      .maybeSingle();
229	
230	    const frete = parseFloat(rest?.frete_motoboy ?? 0);
231	    const total = subtotal + frete;
232	
233	    // Resolve customer_id — busca existente ou cria novo ao primeiro pedido
234	    let customerId = body.customer_id ?? null;
235	    if (!customerId && body.user_id) {
236	      const { data: c } = await this.supabase.client
237	        .from('customers')
238	        .select('id')
239	        .eq('user_id', body.user_id)
240	        .maybeSingle();
241	
242	      if (c) {
243	        customerId = c.id;
244	      } else {
245	        // Cria registro de cliente usando dados do user_profile
246	        const { data: profile } = await this.supabase.client
247	          .from('user_profiles')
248	          .select('name, email')
249	          .eq('id', body.user_id)
250	          .maybeSingle();
251	
252	        const { data: novoCliente } = await this.supabase.client
253	          .from('customers')
254	          .insert({
255	            user_id: body.user_id,
256	            name: profile?.name ?? 'Cliente',
257	            email: profile?.email ?? null,
258	          })
259	          .select('id')
260	          .single();
261	
262	        if (novoCliente) customerId = novoCliente.id;
263	      }
264	    }
265	
266	    // Geocodifica o endereço do cliente em background (best-effort) — só quando a comissão
