1	import React, { useState, useEffect, useCallback } from 'react';
2	import { useNavigate } from 'react-router-dom';
3	import {
4	  listarImpressoras, criarImpressora, atualizarImpressora, removerImpressora,
5	  getImpressorasDetectadas,
6	} from '../../services/restauranteService';
7	import { PONTO_PREPARO_ICONES } from '../../config/pontoPreparoIcones';
8	import Icon from '../../components/AppIcon';
9	import RestauranteHeader from '../../components/restaurante/RestauranteHeader';
10	
11	// Cadastro focado em pontos de preparo (Cozinha, Bar, Churrasqueira, Drinks...) —
12	// cada um vira automaticamente uma entrada no menu lateral + tela dedicada, mesmo
13	// padrão das telas fixas de Cozinha/Bar (ver usePontosPreparoLinks). Por baixo é
14	// só uma impressora com ponto_preparo=true — a tela de Impressoras continua sendo
15	// o lugar pra impressoras que não geram tela (recibo, sangria/acréscimo).
16	const RestaurantePontosPreparo = () => {
17	  const navigate = useNavigate();
18	  const [pontos, setPontos] = useState([]);
19	  const [detectadas, setDetectadas] = useState([]);
20	  const [mostrarForm, setMostrarForm] = useState(false);
21	  const [editando, setEditando] = useState(null);
22	  const [nome, setNome] = useState('');
23	  const [icone, setIcone] = useState(PONTO_PREPARO_ICONES[0]);
24	  const [tipoConexao, setTipoConexao] = useState('rede');
25	  const [endereco, setEndereco] = useState('');
26	  const [nomeSistema, setNomeSistema] = useState('');
27	  const [erro, setErro] = useState(null);
28	  const [salvando, setSalvando] = useState(false);
29	
30	  const carregar = useCallback(() => {
31	    listarImpressoras().then((lista) => setPontos((lista ?? []).filter((i) => i.ponto_preparo)));
32	    getImpressorasDetectadas().then(setDetectadas).catch(() => {});
33	  }, []);
34	  useEffect(() => { carregar(); }, [carregar]);
35	
36	  const abrirNovo = () => {
37	    setEditando(null);
38	    setNome(''); setIcone(PONTO_PREPARO_ICONES[0]); setTipoConexao('rede'); setEndereco(''); setNomeSistema('');
39	    setErro(null);
40	    setMostrarForm(true);
41	  };
42	
43	  const abrirEdicao = (ponto) => {
44	    setEditando(ponto);
45	    setNome(ponto.nome); setIcone(ponto.icone || PONTO_PREPARO_ICONES[0]);
46	    setTipoConexao(ponto.tipo_conexao); setEndereco(ponto.endereco ?? ''); setNomeSistema(ponto.nome_sistema ?? '');
47	    setErro(null);
48	    setMostrarForm(true);
49	  };
50	
51	  const salvar = async (e) => {
52	    e.preventDefault();
53	    setErro(null);
54	    setSalvando(true);
55	    try {
56	      const body = {
57	        nome: nome.trim(),
58	        // setor não tem mais papel de filtro pra ponto de preparo (a tela usa o
59	        // id da impressora direto) — mantido só porque a coluna é obrigatória.
60	        setor: nome.trim(),
61	        tipo_conexao: tipoConexao,
62	        endereco: endereco || undefined,
63	        nome_sistema: nomeSistema || undefined,
64	        ponto_preparo: true,
65	        icone,
66	      };
67	      if (editando) await atualizarImpressora(editando.id, body);
68	      else await criarImpressora(body);
69	      setMostrarForm(false);
70	      carregar();
71	    } catch (err) {
72	      setErro(err.message);
73	    } finally {
74	      setSalvando(false);
75	    }
76	  };
77	
78	  const toggleAtivo = async (ponto) => {
79	    await atualizarImpressora(ponto.id, { ativo: !ponto.ativo });
80	    carregar();
81	  };
82	
83	  const remover = async (ponto) => {
84	    if (!window.confirm(`Remover o ponto de preparo "${ponto.nome}"? Produtos vinculados a ele deixam de imprimir/aparecer numa tela.`)) return;
85	    await removerImpressora(ponto.id);
86	    carregar();
87	  };
88	
89	  return (
90	    <div className="min-h-screen bg-[#F4F4F5] dark:bg-[#18181B]">
91	      <RestauranteHeader active="/restaurante/pontos-preparo" title="Pontos de Preparo" onRefresh={carregar} />
92	      <div className="max-w-4xl mx-auto p-4">
93	        <p className="text-sm text-[#71717A] dark:text-[#A1A1AA] mb-4">
