95	          sua própria tela — no mesmo padrão das telas de Cozinha e Bar — e uma entrada no menu lateral.
96	          Vincule os produtos ao ponto de preparo certo na tela de Produtos, campo "Impressora / setor".
97	        </p>
98	
99	        <button onClick={abrirNovo}
100	          className="mb-4 px-4 py-2 bg-[#FF441F] text-white text-sm font-bold rounded-xl hover:bg-[#E63A19] flex items-center gap-2">
101	          <Icon name="Plus" size={16} /> Novo ponto de preparo
102	        </button>
103	
104	        {mostrarForm && (
105	          <form onSubmit={salvar} className="bg-white dark:bg-[#27272A] rounded-2xl border border-[#E4E4E7] dark:border-[#3F3F46] p-4 mb-4 space-y-3">
106	            <p className="text-sm font-bold text-[#18181B] dark:text-[#F4F4F5]">{editando ? 'Editar ponto de preparo' : 'Novo ponto de preparo'}</p>
107	            <div>
108	              <label className="text-xs text-[#71717A] dark:text-[#A1A1AA]">Nome</label>
109	              <input value={nome} onChange={(e) => setNome(e.target.value)} required placeholder="Ex: Churrasqueira"
110	                className="w-full border border-[#E4E4E7] dark:border-[#3F3F46] bg-white dark:bg-[#18181B] text-[#18181B] dark:text-[#F4F4F5] rounded-xl px-3 py-2 text-sm" />
111	            </div>
112	            <div>
113	              <label className="text-xs text-[#71717A] dark:text-[#A1A1AA] mb-1 block">Ícone</label>
114	              <div className="flex flex-wrap gap-2">
115	                {PONTO_PREPARO_ICONES.map((ic) => (
116	                  <button key={ic} type="button" onClick={() => setIcone(ic)}
117	                    className={`w-10 h-10 rounded-xl border flex items-center justify-center ${
118	                      icone === ic ? 'border-[#FF441F] bg-[#FF441F]/10 text-[#FF441F]' : 'border-[#E4E4E7] dark:border-[#3F3F46] text-[#71717A] dark:text-[#A1A1AA]'
119	                    }`}>
120	                    <Icon name={ic} size={18} />
121	                  </button>
122	                ))}
123	              </div>
124	            </div>
125	            <div className="grid grid-cols-1 sm:grid-cols-2 gap-3">
